const questions=[
 {id:'tr4q001',kpId:'kp_read_sentence_core',textId:'CROSS',skillIds:['read.sentence-core'],sourceTextId:'shishuo',sourceSentenceId:'sentence:shishuo:guzhi-xuezhe-biyoushi',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'foundation',type:'choice',q:'《師說》「古之學者必有師」若先刪去修飾語，哪一項最能保留句子主幹？',o:['學者有師','古之必有','學者古之','師有學者'],a:'學者有師',explanation:'「古之」修飾「學者」，「必」是副詞；句子的主幹是「學者有師」。先抓主語和核心謂語，可避免被修飾成分干擾。'},
 {id:'tr4q002',kpId:'kp_read_sentence_core',textId:'CROSS',skillIds:['read.sentence-core'],sourceTextId:'lianpo',sourceSentenceId:'sentence:lianpo:qinwang-zuo-zhangtai-jian-xiangru',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'foundation',type:'choice',q:'《廉頗藺相如列傳》「秦王坐章臺見相如」的核心主幹最接近？',o:['秦王見相如','章臺見秦王','相如坐章臺','秦王坐相如'],a:'秦王見相如',explanation:'「坐章臺」交代秦王所在位置，核心動作是「見」，主語是「秦王」，賓語是「相如」。主幹可先抽成「秦王見相如」。'},
 {id:'tr4q003',kpId:'kp_read_sentence_core',textId:'CROSS',skillIds:['read.sentence-core'],sourceTextId:'hongmenyan',sourceSentenceId:'sentence:hongmenyan:peigong-jun-bashang-weide-xiangjian',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'application',type:'choice',q:'《鴻門宴》「沛公軍霸上，未得與項羽相見」中，第二分句的主幹是？',o:['沛公未得與項羽相見','霸上與項羽相見','項羽未得軍霸上','沛公與霸上相見'],a:'沛公未得與項羽相見',explanation:'第二分句承前省略主語「沛公」；補回主語後，主幹是「沛公未得與項羽相見」。閱讀時要把省略成分補回再判斷。'},
 {id:'tr4q004',kpId:'kp_read_sentence_core',textId:'CROSS',skillIds:['read.sentence-core'],sourceTextId:'quanxue',sourceSentenceId:'sentence:quanxue:junzi-boxue-rishenxing',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'application',type:'choice',q:'《荀子・勸學》「君子博學而日參省乎己，則知明而行無過矣」中，結果部分的兩個核心判斷是？',o:['知明、行無過','博學、參省','君子、乎己','日參、省乎己'],a:'知明、行無過',explanation:'「則」引出結果；結果部分由兩個並列主幹組成：「知明」與「行無過」。先找到關係詞，再抽取各分句核心。'},
 {id:'tr4q005',kpId:'kp_read_sentence_core',textId:'CROSS',skillIds:['read.sentence-core'],sourceTextId:'liuguolun',sourceSentenceId:'sentence:liuguolun:liuguo-pomie-bizai-luqin',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'transfer',type:'choice',q:'《六國論》「六國破滅，非兵不利，戰不善，弊在賂秦」中，作者最核心的判斷是？',o:['弊在賂秦','六國有兵','戰爭有利','秦國破滅'],a:'弊在賂秦',explanation:'前面的「非兵不利，戰不善」先排除兩個表面原因，真正要建立的主幹判斷是「弊在賂秦」。抓主幹要同時辨別否定與論斷重心。'},
 {id:'tr4q006',kpId:'kp_read_sentence_core',textId:'CROSS',skillIds:['read.sentence-core'],sourceTextId:'lianpo',sourceSentenceId:'sentence:lianpo:yuyu-qin-yuwuyu-qin',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'transfer',type:'choice',q:'《廉頗藺相如列傳》「欲予秦，秦城恐不可得，徒見欺；欲勿予，即患秦兵之來」可先抽成哪兩個選擇主幹？',o:['予秦／勿予','得城／見欺','秦兵／秦城','欲予／患來'],a:'予秦／勿予',explanation:'整段是在比較「把璧給秦」與「不把璧給秦」兩個選擇，再分別說明風險。先抽出「予秦／勿予」，再讀後面的結果，結構會清楚很多。'},

 {id:'tr4q007',kpId:'kp_read_context_clues',textId:'CROSS',skillIds:['read.context-clues'],sourceTextId:'quanxue',sourceSentenceId:'sentence:quanxue:jia-zhouji-feinengshui-juejianghe',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'foundation',type:'choice',q:'《荀子・勸學》「假舟楫者，非能水也，而絕江河」依上下文推斷，「絕」最接近？',o:['橫渡','斷絕交往','停止','消失'],a:'橫渡',explanation:'上文說借助舟船，後文接「江河」，可由工具和賓語推知「絕江河」是橫渡江河。即使不熟「絕」這個義項，也能靠上下文推斷。'},
 {id:'tr4q008',kpId:'kp_read_context_clues',textId:'CROSS',skillIds:['read.context-clues'],sourceTextId:'shishuo',sourceSentenceId:'sentence:shishuo:xiaoxue-er-dayi',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'foundation',type:'choice',q:'《師說》「小學而大遺，吾未見其明也」中，從「小學」與「大遺」的對舉可推斷「遺」最接近？',o:['捨棄／忽略','贈送','留下遺產','遺失物件'],a:'捨棄／忽略',explanation:'「小」與「大」相對，「學」與「遺」也形成反向關係；因此「大遺」是把重要的大道理捨棄、忽略，而不是現代常說的遺失物品。'},
 {id:'tr4q009',kpId:'kp_read_context_clues',textId:'CROSS',skillIds:['read.context-clues'],sourceTextId:'lianpo',sourceSentenceId:'sentence:lianpo:zuoyou-yuren-xiangru-jie-mi',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'application',type:'choice',q:'《廉頗藺相如列傳》「相如張目叱之，左右皆靡」中，依「張目叱之」後的反應推斷，「靡」最接近？',o:['退卻／倒退','華麗','細小','順從命令前進'],a:'退卻／倒退',explanation:'相如怒目喝斥後，秦王左右侍從的合理反應是退縮。由前後動作因果可推知「靡」在此有退卻、倒下之意。'},
 {id:'tr4q010',kpId:'kp_read_context_clues',textId:'CROSS',skillIds:['read.context-clues'],sourceTextId:'lunyu',sourceSentenceId:'sentence:lunyu:zihan:suihan-songbai-houdiao',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'application',type:'choice',q:'《論語》「歲寒，然後知松柏之後凋也」中，從「歲寒」與植物狀態可推斷「凋」是？',o:['凋謝／枯萎','開花','生長','結果'],a:'凋謝／枯萎',explanation:'「歲寒」提供季節線索，「松柏之後凋」是在寒冷時仍較晚凋謝。利用情境常識即可推知「凋」不是生長或開花。'},
 {id:'tr4q011',kpId:'kp_read_context_clues',textId:'CROSS',skillIds:['read.context-clues'],sourceTextId:'hongmenyan',sourceSentenceId:'sentence:hongmenyan:xiangbo-yibi-peigong',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'transfer',type:'choice',q:'《鴻門宴》「項伯亦拔劍起舞，常以身翼蔽沛公，莊不得擊」中，「蔽」可由哪個結果推知是「遮護」？',o:['莊不得擊','項伯拔劍','沛公飲酒','范增起出'],a:'莊不得擊',explanation:'關鍵線索是「莊不得擊」：項莊無法刺擊沛公，說明項伯用身體像鳥翼般擋住、遮護沛公。結果句直接限制了「蔽」的合理詞義。'},
 {id:'tr4q012',kpId:'kp_read_context_clues',textId:'CROSS',skillIds:['read.context-clues'],sourceTextId:'liuguolun',sourceSentenceId:'sentence:liuguolun:fengzhi-mifan-qinzhi-yuji',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'transfer',type:'choice',q:'《六國論》「奉之彌繁，侵之愈急」中，由「彌」與「愈」平行可推斷「彌」最接近？',o:['更加','停止','偶爾','已經'],a:'更加',explanation:'兩句結構平行：「彌繁」對「愈急」。既然「愈」表示更加，就可反推「彌」也有更加、越發之意。這是利用平行結構作語義線索。'},

 {id:'tr4q013',kpId:'kp_read_logical_relation',textId:'CROSS',skillIds:['read.logical-relation'],sourceTextId:'lunyu',sourceSentenceId:'sentence:lunyu-xueer:ren-buzhi-er-buyun',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'foundation',type:'choice',q:'《論語》「人不知而不慍」前後兩部分主要是甚麼關係？',o:['轉折：別人不了解，卻不惱怒','因果：不了解所以惱怒','目的：為了不惱怒而求知','並列：兩件互不相關的事'],a:'轉折：別人不了解，卻不惱怒',explanation:'按常情，被人不了解可能會惱怒；句子卻說「不慍」，所以前後形成逆轉。判斷邏輯關係不能只看連詞，也要看語意預期。'},
 {id:'tr4q014',kpId:'kp_read_logical_relation',textId:'CROSS',skillIds:['read.logical-relation'],sourceTextId:'quanxue',sourceSentenceId:'sentence:xunzi-quanxue:buji-kui-bu-wuyi-zhilili',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'foundation',type:'choice',q:'《荀子・勸學》「不積跬步，無以至千里」最接近哪種邏輯關係？',o:['條件與結果','轉折','並列列舉','讓步'],a:'條件與結果',explanation:'前半提出缺少的條件「不積跬步」，後半指出結果「無以至千里」。可整理為「若不累積小步，就無法到達千里」。'},
 {id:'tr4q015',kpId:'kp_read_logical_relation',textId:'CROSS',skillIds:['read.logical-relation'],sourceTextId:'shishuo',sourceSentenceId:'sentence:shishuo:aizi-zeshi-yushen-chishi',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'application',type:'choice',q:'《師說》「愛其子，擇師而教之；於其身也，則恥師焉」兩部分主要構成？',o:['對比／轉折','因果','時間先後','假設'],a:'對比／轉折',explanation:'同一類人對兒子「擇師」，對自己卻「恥師」，兩種態度互相矛盾。讀出這個對比，才明白韓愈的批評重點。'},
 {id:'tr4q016',kpId:'kp_read_logical_relation',textId:'CROSS',skillIds:['read.logical-relation'],sourceTextId:'liuguolun',sourceSentenceId:'sentence:liuguolun:gouyi-tianxia-zhida',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'application',type:'choice',q:'《六國論》「苟以天下之大，下而從六國破亡之故事，是又在六國下矣」的「苟……是……」主要表達？',o:['假設與結果','轉折','原因與目的','並列'],a:'假設與結果',explanation:'「苟」提出假設：如果以今日天下之大仍重蹈六國覆轍；「是」承接推論結果。閱讀時可先改寫成「如果……那麼……」。'},
 {id:'tr4q017',kpId:'kp_read_logical_relation',textId:'CROSS',skillIds:['read.logical-relation'],sourceTextId:'lianpo',sourceSentenceId:'sentence:lianpo:yuyu-qin-yuwuyu-qin',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'transfer',type:'choice',q:'《廉頗藺相如列傳》「欲予秦……；欲勿予……」這段安排最主要呈現哪種關係？',o:['兩個互相排斥的選擇及各自風險','單一原因推導單一結果','時間順序','讓步後轉折'],a:'兩個互相排斥的選擇及各自風險',explanation:'「予秦」和「勿予」是兩個相反選項，後面分別接「恐不可得、徒見欺」與「患秦兵之來」。把它看成兩條選擇分支，較容易掌握決策困境。'},
 {id:'tr4q018',kpId:'kp_read_logical_relation',textId:'CROSS',skillIds:['read.logical-relation'],sourceTextId:'hongmenyan',sourceSentenceId:'sentence:hongmenyan:suoyi-qianjiang-shouguan',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'transfer',type:'choice',q:'《鴻門宴》「所以遣將守關者，備他盜之出入與非常也」主要是在補充甚麼邏輯？',o:['解釋行動原因','提出相反意見','描述時間先後','列舉兩個無關事件'],a:'解釋行動原因',explanation:'「所以遣將守關者」先提出需要解釋的行動，後面的「備他盜之出入與非常也」交代理由。可整理成「之所以……，是為了／因為……」。'},

 {id:'tr4q019',kpId:'kp_syn_negative_patterns',textId:'CROSS',skillIds:['syn.negative-patterns'],sourceTextId:'quanxue',sourceSentenceId:'sentence:xunzi-quanxue:buji-kui-bu-wuyi-zhilili',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'foundation',type:'choice',q:'《荀子・勸學》「不積跬步，無以至千里」中的「無以＋動詞」應整體理解為？',o:['沒有辦法／條件可以……','不要用……','沒有因為……','尚未開始……'],a:'沒有辦法／條件可以……',explanation:'「無以至千里」不是逐字譯作「沒有以到千里」，而是固定否定結構：「沒有可以用來達到千里的辦法／條件」。'},
 {id:'tr4q020',kpId:'kp_syn_negative_patterns',textId:'CROSS',skillIds:['syn.negative-patterns'],sourceTextId:'lunyu',sourceSentenceId:'sentence:lunyu:ji-suo-buyu-wushi-yuren',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'foundation',type:'choice',q:'《論語》「己所不欲，勿施於人」中的「勿」屬哪一種否定？',o:['禁止／勸止：不要','未然：尚未','判斷否定：不是','能力否定：不能'],a:'禁止／勸止：不要',explanation:'「勿＋動詞」常用來禁止或勸止行為；「勿施於人」就是「不要施加給別人」。它和陳述事實的「不」不同。'},
 {id:'tr4q021',kpId:'kp_syn_negative_patterns',textId:'CROSS',skillIds:['syn.negative-patterns'],sourceTextId:'shishuo',sourceSentenceId:'sentence:shishuo:ren-fei-shengerzhizhi',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'application',type:'choice',q:'《師說》「人非生而知之者，孰能無惑」中，「非……者」主要是否定甚麼？',o:['否定身分類判斷：人不是天生就全都懂的人','表示尚未發生','表示禁止','表示沒有方法'],a:'否定身分類判斷：人不是天生就全都懂的人',explanation:'「非」常用來否定判斷，相當於「不是」。這裡先否定「人是生而知之者」這個判斷，再用反問推出人人都會有疑惑。'},
 {id:'tr4q022',kpId:'kp_syn_negative_patterns',textId:'CROSS',skillIds:['syn.negative-patterns'],sourceTextId:'lunyu',sourceSentenceId:'sentence:lunyu-xueer:weizhi-youye',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'application',type:'choice',q:'《論語》「不好犯上，而好作亂者，未之有也」中的「未之有也」最合理的現代語序是？',o:['未有之也／從未有這種情況','之未有也／這尚未擁有','未之也有／尚未卻有','有未之也／有一個未然'],a:'未有之也／從未有這種情況',explanation:'「未」是否定副詞；否定句中代詞賓語「之」前置，所以「未之有」可還原為「未有之」。這是「否定＋賓語前置」的常見組合。'},
 {id:'tr4q023',kpId:'kp_syn_negative_patterns',textId:'CROSS',skillIds:['syn.negative-patterns'],sourceTextId:'chenshe-shijia',sourceSentenceId:'sentence:chenshe:gou-fugui-wu-xiangwang',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'transfer',type:'choice',q:'《陳涉世家》「苟富貴，無相忘」中的「無」最適合譯作？',o:['不要','沒有','無法','尚未'],a:'不要',explanation:'這裡的「無」用在命令／勸止語氣中，相當於「毋」或「勿」，整句是「如果有一天富貴了，不要互相忘記」。不能機械譯成「沒有」。'},
 {id:'tr4q024',kpId:'kp_syn_negative_patterns',textId:'CROSS',skillIds:['syn.negative-patterns'],sourceTextId:'lunyu',sourceSentenceId:'sentence:lunyu:zihan:sanjun-keduoshuai',sourceKind:'classical-canon',transferLevel:2,difficultyTier:'transfer',type:'choice',q:'《論語》「三軍可奪帥也，匹夫不可奪志也」中的「不可＋動詞」主要表示？',o:['不能／不可以做某事','尚未做某事','不要做某事的命令','不是某種身分'],a:'不能／不可以做某事',explanation:'「不可奪志」表示人的志向不能被強行改變；「不可＋動詞」是否定可能性或許可性，和「勿＋動詞」的直接禁止語氣不同。'}
];

